const chalk = require('chalk');
const fs = require('fs-extra');
const path = require('path');

const MARKER =
  '<!-- Generated by ContextKit (@nolrm/contextkit) https://www.npmjs.com/package/@nolrm/contextkit -->';
const MARKER_END = '<!-- End ContextKit -->';
const LEGACY_MARKER_V1 = '<!-- Generated by ContextKit -->';
const LEGACY_MARKER = '<!-- Generated by Vibe Kit -->';
const LEGACY_MARKER_END = '<!-- End Vibe Kit -->';

/**
 * Writes `content` between the ContextKit markers in `filePath` — replacing an
 * existing block (current or legacy markers), appending below other content,
 * or creating the file. Text outside the markers is never touched.
 */
async function writeMarkedBlock(filePath, content) {
  const dir = path.dirname(filePath);
  if (dir !== '.') {
    await fs.ensureDir(dir);
  }

  const markedContent = `${MARKER}\n${content}\n${MARKER_END}`;

  if (await fs.pathExists(filePath)) {
    const existing = await fs.readFile(filePath, 'utf-8');

    // Check for current or legacy markers
    const hasCurrentMarker = existing.includes(MARKER);
    const hasLegacyMarkerV1 = existing.includes(LEGACY_MARKER_V1);
    const hasLegacyMarker = existing.includes(LEGACY_MARKER);

    if (hasCurrentMarker || hasLegacyMarkerV1 || hasLegacyMarker) {
      const activeMarker = hasCurrentMarker
        ? MARKER
        : hasLegacyMarkerV1
          ? LEGACY_MARKER_V1
          : LEGACY_MARKER;
      const activeMarkerEnd =
        hasLegacyMarker && !hasCurrentMarker && !hasLegacyMarkerV1 ? LEGACY_MARKER_END : MARKER_END;
      const before = existing.substring(0, existing.indexOf(activeMarker));
      const afterMarkerEnd = existing.indexOf(activeMarkerEnd);
      const after =
        afterMarkerEnd !== -1 ? existing.substring(afterMarkerEnd + activeMarkerEnd.length) : '';
      await fs.writeFile(filePath, before + markedContent + after);
    } else {
      // Append below existing content
      await fs.writeFile(filePath, existing.trimEnd() + '\n\n' + markedContent + '\n');
    }
  } else {
    await fs.writeFile(filePath, markedContent + '\n');
  }
}

class BaseIntegration {
  constructor() {
    if (new.target === BaseIntegration) {
      throw new Error('BaseIntegration is abstract and cannot be instantiated directly');
    }
    this.name = '';
    this.displayName = '';
    this.generatedFiles = [];
    this.bridgeFiles = [];
    this.platformDir = '';
  }

  // Returns true when all generated files exist AND the version in the bridge
  // file matches the current package version. Returns false if anything is
  // missing or outdated — triggering a full regeneration.
  async isUpToDate() {
    // All CK-generated files must be present
    for (const file of this.generatedFiles) {
      if (!(await fs.pathExists(file))) return false;
    }

    // AGENTS.md and this integration's own bridge file (if any) must carry
    // the current package version
    for (const versioned of ['AGENTS.md', ...this.bridgeFiles.slice(0, 1)]) {
      if (!(await fs.pathExists(versioned))) return false;
      try {
        const pkg = require('../../package.json');
        const content = await fs.readFile(versioned, 'utf-8');
        const match = content.match(/Version:\s*([0-9]+\.[0-9]+\.[0-9]+)/);
        if (!match || match[1] !== pkg.version) return false;
      } catch {
        return false;
      }
    }

    return true;
  }

  async install(force = false) {
    if (!force && (await this.isUpToDate())) {
      try {
        const pkg = require('../../package.json');
        console.log(
          chalk.green(`  ✓ ${this.displayName} integration is up to date (v${pkg.version})`)
        );
      } catch {
        console.log(chalk.green(`  ✓ ${this.displayName} integration is up to date`));
      }
      return;
    }

    if (this.platformDir) {
      await fs.ensureDir(this.platformDir);
    }
    // AGENTS.md first — bridge files import or mirror it
    await this.writeAgentsMd();
    await this.generateFiles();
  }

  async writeAgentsMd() {
    await require('./agents-md').writeAgentsMd();
  }

  async generateFiles() {
    throw new Error('generateFiles() must be implemented by subclass');
  }

  async validate() {
    const results = { valid: true, missing: [], present: [] };

    const allFiles = [...this.generatedFiles, ...this.bridgeFiles];
    for (const file of allFiles) {
      if (await fs.pathExists(file)) {
        results.present.push(file);
      } else {
        results.missing.push(file);
        results.valid = false;
      }
    }

    return results;
  }

  async writeBridgeFile(filePath, content) {
    await writeMarkedBlock(filePath, content);
  }

  async writeGeneratedFile(filePath, content) {
    const dir = path.dirname(filePath);
    if (dir !== '.') {
      await fs.ensureDir(dir);
    }
    await fs.writeFile(filePath, content);
  }

  showUsage() {
    console.log('');
    console.log(chalk.dim(`  See .contextkit/standards/ for project standards`));
  }
}

module.exports = BaseIntegration;
module.exports.writeMarkedBlock = writeMarkedBlock;
